type NewPost = {
  title?: string
  content?: string
}

export async function GET() {
  const posts = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' },
  ]

  return Response.json(posts)
}

export async function POST(request: Request) {
  const body: NewPost = await request.json()
  const { title, content } = body

  if (!title || !content) {
    return Response.json(
      { error: 'Title and content are required' },
      { status: 400 }
    )
  }

  const newPost = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }

  return Response.json(newPost, { status: 201 })
}

type UpdatePost = {
  title?: string
  content?: string
}

type Props = {
  params: Promise<{ id: string }>
}

export async function GET(_request: Request, { params }: Props) {
  const { id } = await params

  const post = {
    id: parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return Response.json(post)
}

export async function PUT(request: Request, { params }: Props) {
  const { id } = await params
  const body: UpdatePost = await request.json()
  const { title, content } = body

  const updatedPost = {
    id: parseInt(id, 10),
    title: title ?? `Post ${id}`,
    content: content ?? `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return Response.json(updatedPost)
}

export async function DELETE(_request: Request, { params }: Props) {
  const { id } = await params

  return Response.json({ message: `Post ${id} deleted successfully` })
}

